//! Файл: settings/catalog/gate.rs
//! Что делает: настройки, нужные только бирже Gate (решение 135), — интервалы каналов WebSocket по её документации,
//! пауза после 429, глубина поиска ордера по своему ID, вариант списания комиссии (скидка GT) и фоновое получение
//! минимума депозита (решение 143). Значений нет. venue.book_interval, venue.rate_limit_pause_ms и
//! venue.fee_deduction (вариант bnb) использует и Binance (решение 160).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Площадки — Gate»).

use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 135. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static GATE: &[SettingDef] = &[
    d("Площадки", "venue.book_interval", K::Choice, L::None, "интервал", V, "Решение 135, только Gate: интервал снимков стакана канала spot.order_book (официально — 100ms или 1000ms, Spot WebSocket v4). Не задан — стаканы Gate не подписываются. Binance (решение 160): интервал потоков частичного стакана <symbol>@depth<N>[@100ms] и изменений стакана окна (официально 1000ms или 100ms); не задан — стаканы Binance не подписываются").choices(&["100ms", "1000ms"]),
    d("Окна", "venue.window_diff_interval", K::Choice, L::None, "интервал", V, "Решение 135, только Gate: интервал канала изменений стакана spot.order_book_update для окон (официально — 20ms при глубине 20 или 100ms при глубине 100). Не задан — изменения стакана Gate в окна не пишутся (снимки пишутся)").choices(&["20ms", "100ms"]).optional(),
    d("Площадки", "venue.rate_limit_pause_ms", K::Integer, L::Positive, "мс", V, "Решение 135, только Gate: после ответа «слишком часто» (HTTP 429, TOO_MANY_REQUESTS) запросы к площадке не отправляются столько миллисекунд, если площадка не прислала Retry-After (в документации Gate его нет; есть заголовок X-Gate-RateLimit-Reset-Timestamp, который транспорт пока не читает). Не задана — паузы нет (в тексте ошибки сказано). Binance (решение 160): пауза после HTTP 418/429 или кода −1003, если Retry-After не пришёл (у /sapi — свой предел на эндпоинт; пауза /sapi не останавливает /api)"),
    d("Площадки", "venue.order_history_limit", K::Integer, L::Positive, "ордеров", V, "Решение 135, только Gate: сколько законченных ордеров пары читать (GET /spot/orders?status=finished, limit; в документации — «default 100») при поиске ордера по своему ID, если итог постановки неизвестен. Не задана — ордер не ставится (поиск нужен после постановки — проверяется до неё)"),
    d("Площадки", "venue.fee_deduction", K::Choice, L::None, "вариант", V, "Решение 135 и 158 (Тигран 04–05.11), только Gate: чем считать торговую комиссию. coin — обычная ставка taker_fee в монете сделки (покупка уменьшает купленное количество, продажа — выручку USDT); если на счёте включена скидка GT — всё равно обычная ставка (худший случай), сделки идут. gt — ставка со скидкой gt_taker_fee в GT, пока на счёте включена скидка и свободного GT не меньше venue.gt_min_balance (баланс — раз в venue.gt_balance_poll_s); GT кончился или скидка выключена — сам переходит на обычную ставку. Факт комиссии — из ордера. Не задана — котировок Gate нет. Binance (решения 158, 160): coin — полная ставка (стандартная + налог + специальная, taker + buyer/seller) в монете сделки, даже если скидка включена; bnb — стандартная × discount + налог + специальная в монете скидки (BNB), пока скидка включена на аккаунте и паре и монеты скидки не меньше venue.discount_min_balance, иначе — полная ставка. gt — только Gate, bnb — только Binance").choices(&["coin", "gt", "bnb"]),
    d("Площадки", "venue.gt_min_balance", K::Decimal, L::Positive, "GT", V, "Решение 158 (Тигран 05.11), только Gate: при venue.fee_deduction = gt комиссия считается со скидкой GT, только пока свободного GT на споте не меньше этого; меньше, баланс не прочитан или замер устарел — обычная ставка в монете сделки (сделки идут дальше). Не задана — скидка в расчёте не применяется").optional(),
    d("Площадки", "venue.gt_balance_poll_s", K::Integer, L::Positive, "с", V, "Решение 158, только Gate: как часто читать свободный GT на споте (GET /spot/accounts?currency=GT). Замер старше двух кругов считается устаревшим — обычная ставка. Не задана — баланс GT не читается, скидка в расчёте не применяется").optional(),
    d("Площадки", "venue.deposit_info_requests_per_sec", K::Integer, L::Positive, "запросов/с", V, "Решение 143, только Gate: минимум депозита Gate отдаёт только в ответе адреса депозита (GET /wallet/deposit_address, min_deposit_amount). Бот фоном спрашивает адрес депозита в сети BSC по каждой монете подписки — столько запросов в секунду (лимит Gate для кошелька — 200 запросов за 10 с на эндпоинт по UID). Пока минимум монеты не получен — действует venue.deposit_min_absent_ok. Не задана — фоновых запросов нет"),
    d("Площадки", "venue.deposit_info_refresh_s", K::Integer, L::Positive, "с", V, "Решение 143, только Gate: пауза между кругами фонового запроса адресов депозита (минимум депозита мог измениться). Итог круга — запись venue.deposit_info в журнале. Не задана — фоновых запросов нет"),
];
